import csv

rows = list(csv.reader(open('/work/workspace/documents/bank_checking_2024-12_to_2026-01.csv')))
header, data = rows[0], rows[1:]

def cls(date, desc, amt):
    d = desc.upper(); a = float(amt)
    if 'TESSARO STUDIOS INV 1041' in d:
        return ('prior_year', '', 'Received 2024-12-27; cash-method income of the 2024 return (prior year). '
                'Not on 2025 Sch C; not in Tessaro 2025 1099-NEC.')
    if 'TESSARO' in d:
        return ('business_income', '1', 'Direct ACH, outside PayHub. 2025 Tessaro ACH deposits total 9,400.00, '
                'exactly matching Tessaro 1099-NEC box 1.')
    if 'PAYHUB' in d:
        return ('business_income', '1', 'Net of processor fees. All 11 payouts = 40,150.85 vs 1099-K gross 41,350.00; '
                'fees 1,199.15 (2.9%) deducted on line 10. Includes Beacon/Orchard payments double-reported on their '
                '1099-NECs (see Q1) - counted once, in the 1099-K gross.')
    if 'LARKSPUR' in d:
        return ('other_schedule', '', 'W-2 wages of employer -> Form 1040 line 1a (not Sch C). Deposits are net pay; '
                'W-2 box 1 = 24,800.00.')
    if 'RENT' in d:
        return ('personal', '', 'Apartment rent - personal (§262). No qualified home-office substantiation in file (Q8).')
    if 'T-MOBILE' in d:
        return ('business_expense', '25', 'Cell phone. ASSUMPTION: 100% business use pending Q3; line 25 total adjusts if lower.')
    if 'SPECTRUM' in d:
        return ('business_expense', '25', 'Internet (not basic local first-line telephone service). ASSUMPTION: 100% business (Q3).')
    if 'FIGMA' in d:
        return ('business_expense', '27a', 'Software subscription (design tool).')
    if 'ADOBE' in d:
        return ('business_expense', '27a', 'Software subscription (Creative Cloud).')
    if 'NETFLIX' in d:
        return ('personal', '', 'Entertainment - personal (§262).')
    if 'ORANGETHEORY' in d:
        return ('personal', '', 'Gym membership - personal (§262).')
    if 'H-E-B' in d:
        return ('personal', '', 'Groceries - personal (§262). See Q6 if any business purchases included.')
    if 'HISCOX' in d:
        return ('business_expense', '15', 'Professional liability insurance premium - line 15 (not health).')
    if 'IRS USATAXPYMT' in d:
        return ('tax_payment', '', 'Federal estimated tax payment; not deductible on any schedule; credits against Form 1040 tax.')
    if 'CAPITAL FACTORY' in d:
        return ('business_expense', '20b', 'Coworking membership (8 payments May-Dec x 350 = 2,800) - line 20b rent/lease, '
                'other business property.')
    if 'BLUE CROSS BLUE SHIELD' in d:
        return ('other_schedule', '', 'Health insurance premiums (8 x 380 = 3,040, May-Dec). NOT Sch C line 15; self-employed '
                'health insurance deduction, Schedule 1 line 17.')
    if 'AIR 118 AUS-DEN' in d:
        return ('personal', '', 'PROVISIONAL: 6/13 AUS-DEN flight; no business purpose in file. Not claimed pending Q4; '
                'would move to line 24a if business.')
    if 'AIR 526 AUS-SFO' in d:
        return ('business_expense', '24a', 'AUS-SFO round trip for DesignWeek SF conference (Q5).')
    if 'HOTEL ZEPHYR' in d:
        return ('business_expense', '24a', 'Lodging during DesignWeek SF trip - away-from-home overnight (Q5).')
    if 'DESIGNWEEK' in d:
        return ('business_expense', '27a', 'Conference registration - professional development, line 27a (not travel).')
    if 'MARINA DELI' in d:
        return ('business_expense', '24b', 'Meal during SF business trip (Q5). 50% limit: 64.00 x 50% = 32.00 claimed on 24b.')
    if 'TARTINE' in d:
        return ('business_expense', '24b', 'Meal during SF business trip (Q5). 50% limit: 126.00 x 50% = 63.00 claimed on 24b.')
    if 'WEDDING GIFT' in d:
        return ('personal', '', 'Personal gift (§262).')
    if 'MACBOOK PRO' in d:
        return ('business_expense', '27a', 'MacBook Pro 14, 2,149.00. De minimis safe harbor election, Reg. 1.263(a)-1(f) '
                '(item <= 2,500; election statement to be attached); expense on 27a instead of line 13 depreciation. '
                'ASSUMPTION: 100% business use (Q6).')
    raise ValueError('unclassified: ' + desc)

out = [['date', 'description', 'amount', 'classification', 'schedule_c_line', 'note']]
counts = {}
for r in data:
    date, desc, amt, bal = r
    c, line, note = cls(date, desc, amt)
    counts[c] = counts.get(c, 0) + 1
    out.append([date, desc, amt, c, line, note])

with open('/work/workspace/deliverable/classification.csv', 'w', newline='') as f:
    csv.writer(f).writerows(out)
print('rows written:', len(out) - 1)
print(counts)

