import csv, re, io
from decimal import Decimal as D

rows = list(csv.DictReader(open("/work/workspace/documents/bank_checking_2024-12_to_2026-01.csv")))
assert len(rows) == 149

def money(s):
    neg = s.startswith("(")
    v = D(s.strip("()"))
    return -v if neg else v

def date(s):
    m, d, y = s.split("/")
    return f"{y}-{int(m):02d}-{int(d):02d}"

def y2025(s):
    m, d, y = s.split("/")
    return int(y) == 2025

def payhub_net(desc, amt):
    return re.search(r"PAYPAL\*SEND/\d+|STRIPE\*?SND/\d+", desc)

def payhub_gross(desc, amt):
    return re.search(r"PAYPAL\*SEND(?![/\d])|STRIPE\*?SND(?![/\d])", desc) and amt > 0

def beacon_like(desc, amt):
    return "BEACON CONSULTING PAYMENT" in desc and amt > 0

payhub_pairs = {
    "2025-01-31|2473.40": "2024-12-31|3039.00",
    "2025-02-25|3417.80": "2025-01-31|4576.00",
    "2025-03-03|4773.50": "2025-01-31|4891.00",
    "2025-03-31|5906.50": "2025-02-28|6081.00",
    "2025-04-07|1627.50": "2025-02-28|1673.00",
    "2025-04-28|2744.10": "2025-03-31|3047.00",
    "2025-05-01|2463.35": "2025-04-30|2534.00",
    "2025-05-05|1713.70": "2025-03-31|1763.00",
    "2025-06-02|3149.00": "2025-04-30|3241.00",
    "2025-06-27|2848.90": "2025-05-31|2932.00",
    "2025-07-01|2248.00": "2025-05-31|2313.00",
    "2025-07-30|4187.10": "2025-06-30|4310.00",
    "2025-08-03|3018.15": "2025-06-30|3106.00",
    "2025-08-29|6157.30": "2025-07-31|6340.00",
    "2025-10-02|4345.10": "2025-09-30|4473.00",
    "2025-11-25|3399.85": "2025-10-31|3500.00",
    "2025-12-30|2913.55": "2025-11-29|3000.00",
    "2026-01-29|1947.35": "2025-12-31|2005.00",
}

def classify(desc, amt, ds):
    """Return (classification, schedule_c_line, note)."""
    d = date(ds)
    gross = payhub_gross(desc, amt)
    net = payhub_net(desc, amt) or beacon_like(desc, amt)
    pair = payhub_pairs.get(f"{d}|{amt:.2f}")

    if pair:
        return ("business_income", "1",
                f"PayHub (1099-K) processing payout; gross sale batch {pair.split('|')[0]} ${pair.split('|')[1]} less 2.9% fee (fee verified: gross-amount=2.9%). Gross income counted once per batch on line 1; fee on line 10. Mislabel warning: the 2024 notes called the 3/03/2025 $4,773.50 'BEACON CONSULTING PAYMENT (DEC 2024 invoice)' but it is a PayHub payout net of fee.")
    if gross:
        return ("other_schedule", "",
                "Informational only - gross sale batch reported on Form 1099-K (gross $41,350.00 = $50,750.00 Schedule C income less $9,400.00 Tessaro direct-ACH). NOT a deposit and NOT an additional deduction or income item; the cash reached this account on the paired payout date net of the 2.9% fee. Deducted amount here would double-count.")
    if amt < 0 and payhub_net(desc, -amt):
        return ("other_schedule", "",
                "Informational memo of gross sale batch on the payout date; cash actually credited earlier (see matching payout row). $4891.00 row is mislabeled 'ORCHARD CREATIVE PAYMENT (JAN 2025)' in this feed - it is the gross behind the 3/03/2025 $4,773.50 PayHub payout. Not a separate deduction.")
    if "TESSARO MEDIA GROUP" in desc:
        if not y2025(ds):
            return ("prior_year", "",
                    "Client's 12/27/2024 check, deposited 1/02/2025. Cash-method: 2024 income (part of 2024 gross $46,050 per prior-year notes). Not in Tessaro's 2025 1099-NEC ($9,400). Confirm it was reported on the 2024 return (Q7).")
        return ("business_income", "1",
                "Direct ACH from Tessaro Media Group; 2025 deposits total $9,400.00 = Tessaro 1099-NEC box 1 $9,400.00. Counted in line 1 gross.")
    if "LARKSPUR FOUNDATION" in desc:
        if not y2025(ds):
            return ("prior_year", "",
                    "Wages for Dec 2024 teaching contract - 2024 tax year, not 2025 income. Wages are Form 1040 line 1a (per W-2), never Schedule C.")
        return ("other_schedule", "",
                "Net paycheck from W-2 employment at Larkspur Foundation (gross pay $3,050/pay, net $2,437.85; 8 deposits in 2025). Reported on Form 1040 line 1a per Form W-2 (box 1 $24,800) - not Schedule C income, and gross pay is not a Schedule C deduction.")
    if amt < 0 and "VENMO TRANSFER TO M OKAFOR" in desc:
        return ("transfer", "",
                "Transfer to M. Okafor; 2025 total $2,432.00. Client's notes assert business spending through cash/Venmo but no payee/substantiation provided - not deductible without documentation (Q9).")
    if amt < 0 and "CASH WITHDRAWAL" in desc:
        return ("transfer", "",
                "Cash withdrawal; 2025 total $7,300.00. Client's notes assert these funded business spending, but no receipts or payee records - not deductible without substantiation (Q9).")
    if "FEDERAL ESTIMATED TAX PAYMENT" in desc:
        return ("tax_payment", "",
                "Federal estimated tax payment; 2025 total $6,500.00. Federal income tax is not deductible on Schedule C; carried on Form 1040-V / payment records. 2024 notes mislabeled the 1/07/2025 $2,000 as a Beacon payment - bank description confirms it is a tax payment (Q8).")
    if "UNITED AIRLINES" in desc:
        return ("personal", "",
                "Provisionally personal - Denver trip 6/12-6/17/2025 called a vacation in the client email but 'Business (vacation overlap)' in the mileage log; purpose unverified. Excluded from Schedule C pending Q3. If business: line 24a +$778.00.")
    if "HISCOX INSURANCE" in desc:
        return ("business_expense", "15", "Business liability insurance (client notes: verified). Line 15 total $480.00.")
    if "SFO SOFTWARE" in desc:
        return ("business_expense", "27a", "Design software subscription $540.00 (Jan; client notes: business-use 100% verified). Line 27a.")
    if "ADOBE CREATIVE" in desc:
        return ("business_expense", "27a", "Design software subscription (Jan $499.92, Feb $199.98, Mar $19.98 = $719.88; client notes: verified). Line 27a.")
    if "AUSTIN DESIGN CONFERENCE" in desc:
        return ("business_expense", "27a", "Austin Design Conference registration $650.00 (Feb; client notes: verified, no meals included). Ordinary and necessary; reported on line 27a as other expenses (see line 24a note re travel vs education).")
    if "APPLE INC PURCHASE" in desc:
        return ("business_expense", "27b", "MacBook Pro $2,149.00 bought 2/18/2025 (client notes: 'fully for work'). Capital item; deducted 100% via special allowance (line 27b, sec. 168(k) / Rev. Proc. 2019-25); 50%+ business use required (Q6).")
    if "PAYPAL GIGWORK NET" in desc:
        return ("business_income", "",
                "Duplicate PayHub payout memo line - already counted once at the matching 'PAYPAL*SEND/PAYPAL' credit (see gross/payout pairing). Not additional income.")
    if "PAYPAL*SEND/PAYPAL" in desc and amt < 0:
        return ("business_income", "",
                "Memo of gross sale batch; income counted once at payout credit, fee deducted on line 10. Not a separate deduction.")
    if "BLUE CROSS BLUE SHIELD" in desc:
        return ("other_schedule", "",
                "Health insurance premiums, 8 x $380 = $3,040.00 in 2025. Not deductible on Schedule C line 15 (not business liability insurance); self-employed health insurance goes on Schedule 1 line 17, subject to the tax-liability and >2% S-corp-shareholder limits. See not_on_schedule_c.")
    if "SPRING" in desc and "INTERNET" in desc:
        return ("business_expense", "25", "Internet $105/mo x 8 = $840.00 (May-Dec). Business-use % unverified; client notes estimate 60% - applied 60% (line 25 total with cell). Q5.")
    if "AT&T WIRELESS" in desc:
        return ("business_expense", "25", "Cell $85/mo x 12 = $1,020.00. Business-use % unverified; client notes estimate 60% - applied 60% (line 25 total with internet). Q5.")
    if "CAPITAL FACTORY" in desc:
        return ("business_expense", "20b", "Coworking rent $350/mo; 8 payments in 2025 (May-Dec) = $2,800.00 (client notes' '(12 payments)' mixes in 2024; bank verifies 8 x $350). Line 20b.")
    if "HOTEL ZEPHYR" in desc:
        return ("business_expense", "24a", "Hotel Zephyr 11/16/2025 $618.00, SF DesignWeek trip with the 11/15 Ryan airfare; client notes: business, verified. Line 24a.")
    if "RYAN AIRFARE" in desc:
        return ("business_expense", "24a", "AUS-SFO airfare 11/15/2025 $412.00 for SF DesignWeek (client notes: conference, verified). Line 24a.")
    if "SFO VENUE CONF" in desc:
        return ("business_expense", "27a", "DesignWeek conference fee $500.00 11/16/2025 (client notes: business). Reported line 27a with the other conference fee.")
    if "MISC VENUE CATERING" in desc:
        return ("personal", "", "Venue catering $400.00; no business purpose in records and client notes omit it. Treated personal (not on notes' verified list).")
