def classify(r):
    d, amt, dt = r["description"], float(r["amount"]), r["date"]
    if d == "ACH CREDIT TESSARO STUDIOS INV 1041":
        return ("prior_year", "", "Invoice 1041 paid 12/27/2024; cash method -> 2024 return (Sch C instr. excerpt, Cash method)")
