        return ("business_income", "1", "Net payout of PayHub gross reported on 1099-K ($41,350); 2.9% processor fee kept at source -> line 10")
    if d == "ACH CREDIT TESSARO STUDIOS":
        return ("business_income", "1", "Direct ACH (not via PayHub); part of $9,400 1099-NEC reported once")
    if d.startswith("DIRECT DEP LARKSPUR"):
        return ("other_schedule", "", "W-2 wages (net); W-2 box 1 $24,800 -> Form 1040 line 1a; not Schedule C")
    if d.startswith("IRS USATAXPYMT"):
        return ("tax_payment", "", "Federal estimated tax; federal income tax payments are not deductible (no library authority; labeled unverified)")
    if d == "T-MOBILE WIRELESS":
        return ("business_expense", "25", "Cell phone; 80% business-use ASSUMPTION pending client substantiation")
    if d == "SPECTRUM INTERNET":
        return ("business_expense", "25", "Internet; 80% business-use ASSUMPTION pending client substantiation")
    if d == "FIGMA INC SUBSCRIPTION":
        return ("business_expense", "27a", "Business software subscription")
    if d == "ADOBE *CREATIVE CLOUD":
        return ("business_expense", "27a", "Business software subscription")
    if d == "NETFLIX.COM":
        return ("personal", "", "Personal entertainment (26 U.S.C. 262(a))")
    if d == "ORANGETHEORY FITNESS AUSTIN":
        return ("personal", "", "Personal gym membership (26 U.S.C. 262(a))")
    if d.startswith("DEBIT CARD H-E-B"):
        if dt < "2025-01-01":
            return ("prior_year", "", "Groceries, 2024; personal and prior year")
        return ("personal", "", "Groceries (26 U.S.C. 262(a))")
    if d.startswith("ZELLE TO: M. OKAFOR RENT"):
        return ("personal", "", "Residential rent (26 U.S.C. 262(a))")
    if d == "HISCOX PROFESSIONAL LIABILITY":
        return ("business_expense", "15", "Professional liability insurance (not health) -> line 15")
    if d == "CAPITAL FACTORY COWORKING":
        return ("business_expense", "20b", "Coworking membership rent -> line 20b")
    if d == "BLUE CROSS BLUE SHIELD TX PREMIUM":
        return ("other_schedule", "", "Health insurance -> self-employed health insurance deduction, Schedule 1 line 17; NOT line 15")
    if d == "SOUTHWEST AIR 118 AUS-DEN":
        return ("personal", "", "Purpose unknown; no business documentation -> treated personal pending client answer")
    if d.startswith("VENMO: WEDDING GIFT"):
        return ("personal", "", "Personal gift (26 U.S.C. 262(a))")
    if d == "SOUTHWEST AIR 526 AUS-SFO":
        return ("business_expense", "24a", "Airfare to DesignWeek SF conference (10/02)")
    if d == "HOTEL ZEPHYR SAN FRANCISCO":
        return ("business_expense", "24a", "Lodging during DesignWeek SF trip")
    if d == "DESIGNWEEK SF CONFERENCE REG":
        return ("business_expense", "27a", "Professional development / conference registration -> line 27a")
    if d == "SQ *MARINA DELI SAN FRANCISCO":
        return ("business_expense", "24b", "Meal while traveling for DesignWeek; 50% limit")
    if d == "TARTINE MANUFACTORY":
        return ("business_expense", "24b", "Meal during DesignWeek SF trip (SF merchant); 50% limit")
