lark = total(lambda r: r["description"].startswith("DIRECT DEP LARKSPUR"))
bcbs = total(lambda r: r["description"].startswith("BLUE CROSS"))
es = total(lambda r: r["description"].startswith("IRS USATAXPYMT"))
phone = total(lambda r: r["description"] == "T-MOBILE WIRELESS")
net = total(lambda r: r["description"] == "SPECTRUM INTERNET")
figma = total(lambda r: r["description"] == "FIGMA INC SUBSCRIPTION")
adobe = total(lambda r: r["description"].startswith("ADOBE"))
cowork = total(lambda r: r["description"] == "CAPITAL FACTORY COWORKING")
