line28 = round(sum(exp.values()), 2)
line29 = round(line1 - line28, 2)
line31 = line29
net_earn = round(line31 * 0.9235, 2)
se_tax = round(net_earn * 0.153, 2)
half = round(se_tax * 0.5, 2)
print("L1", line1, "exp", exp, "L28", line28, "L29/31", line31)
print("SE", net_earn, se_tax, half, "wage-base check:", 24800 + net_earn)

doc = {
    "tax_year": 2025,
    "lines": {
        "1": line1,
        "9": line9,
        "10": line10,
        "15": line15,
        "20b": line20b,
        "24a": line24a,
        "24b": line24b,
        "25": line25,
        "27a": line27a,
        "28": line28,
        "29": line29,
        "31": line31,
    },
    "schedule_se": {"net_earnings": net_earn, "se_tax": se_tax, "deductible_half": half},
    "not_on_schedule_c": [
        {"item": "Larkspur Interactive W-2 wages (box 1; bank net deposits $19,502.80)", "amount": 24800.00, "where": "Form 1040 line 1a (other_schedule)"},
        {"item": "Blue Cross Blue Shield TX health insurance premiums, May-Dec 2025 (8 x $380)", "amount": 3040.00, "where": "Schedule 1 line 17 - self-employed health insurance; not Schedule C line 15"},
        {"item": "One-half of self-employment tax", "amount": half, "where": "Schedule 1 line 15"},
        {"item": "Federal estimated tax payments Q1-Q3 (1,500 + 2,500 + 2,500)", "amount": 6500.00, "where": "Not deductible; federal income tax payment (rule not addressed in library - unverified)"},
        {"item": "Tessaro Studios invoice 1041 paid 12/27/2024", "amount": 3000.00, "where": "Prior year (2024 return) under cash method"},
        {"item": "Zelle rent to M. Okafor (12 x 1,650)", "amount": 19800.00, "where": "Personal - residential rent, 26 U.S.C. 262(a)"},
        {"item": "Southwest AUS-DEN airfare 06/13/2025 (purpose unknown)", "amount": 389.00, "where": "Treated personal pending client answer (Pub. 463 personal travel)"},
        {"item": "Netflix (12 x 15.49)", "amount": 185.88, "where": "Personal, 26 U.S.C. 262(a)"},
        {"item": "OrangeTheory Fitness (12 x 49)", "amount": 588.00, "where": "Personal, 26 U.S.C. 262(a)"},
        {"item": "H-E-B groceries (12 debits in 2025)", "amount": 2102.95, "where": "Personal, 26 U.S.C. 262(a)"},
        {"item": "Venmo wedding gift", "amount": 200.00, "where": "Personal, 26 U.S.C. 262(a)"},
    ],
    "assumptions": [
        "Beacon ($18,500) and Orchard ($12,200) 1099-NEC payments were processed through PayHub and are inside the 1099-K gross $41,350 (bank payouts $40,150.85 = 97.1% of $41,350 exactly; no other 2025 business credits in bank). Counted once on line 1.",
        "Utilities 80% business use (T-Mobile $1,020 + Spectrum $840); unsupported - question pending.",
        "Mileage: 'other client errands' 1,150 mi treated as business (notebook page 2 not provided).",
        "Marina Deli $64 and Tartine $126 treated as business meals during the DesignWeek trip (50% limit).",
        "MacBook Pro 14 ($2,149) is 100% business use; de minimis safe harbor election to expense on line 27a.",
    ],
}
json.dump(doc, open("/work/workspace/deliverable/schedule_c.json", "w"), indent=2)
print("WROTE classification.csv and schedule_c.json")

