#!/usr/bin/env python3
"""2025 prep for Dana Okafor — current fixture (docs dated 2026-10-22).
Generates deliverable/classification.csv and deliverable/schedule_c.json
from workspace/documents/bank_checking_2024-12_to_2026-01.csv."""
import csv, json

CSV = '/work/workspace/documents/bank_checking_2024-12_to_2026-01.csv'
OUT_CSV = '/work/workspace/deliverable/classification.csv'
OUT_JSON = '/work/workspace/deliverable/schedule_c.json'

rows = list(csv.DictReader(open(CSV)))

# ---------------- classification rules ----------------
def classify(r):
    d = r['description']; amt = float(r['amount'])
    if d.startswith('PAYHUB PAYOUT'):
        return ('business_income', '1', 'PayHub processor payouts; gross receipts reported from 1099-K (Line 1) and net of 2.9% fees; payout detail pending (Q1)')
    if 'TESSARO' in d and amt > 0:
        if r['date'].startswith('2024'):
            return ('prior_year', '', 'Payment received 12/27/2024 — 2024 income (cash method); 2025 Form 1099-NEC covers only 2025 payments')
        return ('business_income', '1', 'Direct ACH from Tessaro Studio; on 2025 Form 1099-NEC ($9,400) and not in PayHub gross')
    if d.startswith('LARKSPUR'):
        return ('other_schedule', '', 'Wages per 2025 Form W-2 (box 1 $24,800) — Form 1040 line 1a, not Schedule C')
    if 'CAPITAL FACTORY' in d and amt > 0:
        return ('other_schedule', '', 'Interest income — Schedule B; not Schedule C self-employment income')
    if 'SOUTHWEST AIRLINES' in d and 'AUS-SFO' in d:
        return ('business_expense', '24a', 'Airfare to San Francisco client meetings (Oct 5-7); substantiated by client email')
    if 'SOUTHWEST AIRLINES' in d and 'AUS-DEN' in d:
        return ('personal', '', 'AUS-DEN flight Jun 13; purpose not stated in any document — treated personal pending client answer (Q2)')
    if 'HOTEL ZEPHYR' in d:
        return ('business_expense', '24a', 'Lodging, SF client-meeting trip Oct 5-7')
    if 'MARINA DELI' in d or 'TARTINE' in d:
        return ('business_expense', '24b', 'Meal on SF trip; 50% limitation (Pub 463): 50% x amount to line 24b; business purpose pending confirmation (Q3)')
    if 'DESIGNWEEK' in d:
        return ('business_expense', '27a', 'Professional development/registration (excerpt: professional development reported on 27a)')
    if 'MACBOOK PRO' in d:
        return ('business_expense', '27a', 'Computer $2,149 < $2,500 de minimis safe harbor (Reg. 1.263(a)-1(f), per excerpt) — expensed; election statement required; 100% business use pending confirmation (Q4)')
    if 'CAPITAL FACTORY' in d:
        return ('business_expense', '20b', 'Coworking space rent $350/month (excerpt: rent reported on line 20b)')
    if d.startswith('T-MOBILE'):
        return ('business_expense', '25', 'Business phone; 100% business use assumed pending substantiation (Q5); IRC 262: any personal share nondeductible')
    if 'SPECTRAM' in d:
        return ('business_expense', '25', 'Internet service; 100% business use assumed pending substantiation (Q5)')
    if d.startswith('HISPOX') or d.startswith('HISCOX'):
        return ('business_expense', '15', 'Insurance other than health (business liability)')
    if 'BLUE CROSS BLUE SHIELD' in d:
        return ('other_schedule', '', 'Health insurance premiums — Schedule 1 line 17 per library excerpt (line 15); not deducted on Schedule C')
    if d.startswith('INTERNAL REVENUE') and 'FED EST PAYMENT' in d:
        return ('tax_payment', '', 'Estimated federal income tax payment — not deductible on Schedule C; credited on Form 1040')
    if d.startswith('ZELLE RENT'):
        return ('personal', '', 'Personal rent')
    if d.startswith('Zelle') and amt > 0:
        return ('personal', '', 'Reversal/refund of personal Zelle payment')
    if 'NETFLIX' in d: return ('personal', '', 'Personal entertainment (IRC 262)')
    if 'SPOTIFY' in d: return ('personal', '', 'Personal subscription (IRC 262)')
    if 'ORINGTHEORY' in d or 'ORANGETHEORY' in d: return ('personal', '', 'Personal gym dues (IRC 262)')
    if d.startswith('H-E-B') or d.startswith('HEB'): return ('personal', '', 'Personal groceries (IRC 262)')
    if d.startswith('TOTAL AFFINIA'): return ('personal', '', 'Personal credit-card payment')
    if d == 'WEDDING GIFT': return ('personal', '', 'Personal gift')
    if 'FIGMA' in d: return ('business_expense', '27a', 'Software subscription (excerpt: software subscriptions on line 27a)')
    if d.startswith('ADOBE'): return ('business_expense', '27a', 'Software subscription (excerpt: software subscriptions on line 27a)')
    return ('other', '', 'Unclassified — review')

cls = [classify(r) for r in rows]

with open(OUT_CSV, 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['date', 'description', 'amount', 'classification', 'schedule_c_line', 'note'])
    for r, (c, ln, note) in zip(rows, cls):
        w.writerow([r['date'], r['description'], f"{float(r['amount']):.2f}", c, ln, note])

# ---------------- aggregation ----------------
def tot(cls_names, desc_test=None, year='2025'):
    s = 0.0
    for r, (c, ln, n) in zip(rows, cls):
        if c in cls_names and r['date'].startswith(year) and (desc_test is None or desc_test(r['description'])):
            s += float(r['amount'])
    return s

hiscox = -tot(['business_expense'], lambda d: 'HISPOX' in d)
phone = -sum(float(r['amount']) for r in rows if r['date'].startswith('2025') and r['description'].startswith('T-MOBILE'))
internet = -sum(float(r['amount']) for r in rows if r['date'].startswith('2025') and 'SPECTRAM' in r['description'])
cowork = -tot(['business_expense'], lambda d: d == 'CAPITAL FACTORY')
airfare_sfo = -sum(float(r['amount']) for r in rows if 'SOUTHWEST AIRLINES' in r['description'] and 'AUS-SFO' in r['description'])
hotel = -sum(float(r['amount']) for r in rows if 'HOTEL ZEPHYR' in r['description'])
meals_100 = sum(float(r['amount']) for r in rows if ('MARINA DELI' in r['description'] or 'TARTINE' in r['description']))
figma = -sum(float(r['amount']) for r in rows if 'FIGMA' in r['description'])
adobe = -sum(float(r['amount']) for r in rows if r['description'].startswith('ADOBE'))
reg = -sum(float(r['amount']) for r in rows if 'DESIGNWEEK' in r['description'])
macbook = -sum(float(r['amount']) for r in rows if 'MACBOOK PRO' in r['description'])
wages = -sum(float(r['amount']) for r in rows if r['date'].startswith('2025') and r['description'].startswith('LARKSPUR'))
bcbs = -sum(float(r['amount']) for r in rows if 'BLUE CROSS BLUE SHIELD' in r['description'])
fed_es = -sum(float(r['amount']) for r in rows if r['description'].startswith('INTERNAL REVENUE'))

# 2025 Form 1099-K (PayHub): box 1 gross $41,350 (61 txns); box 5a $0, 5b $1,866.68.
# Bank PAYHUB PAYOUT total 40,150.85 = 97.1% of 41,350 exactly -> processor fees 2.9% = 1,199.15.
gross_1099k = 41350.00
tessaro_direct = 9400.00          # 2400 + 3100 + 2150 + 1750 (2025 ACH credits; matches 1099-NEC)
line1 = gross_1099k + tessaro_direct
line10 = round(gross_1099k * 0.029, 2)

# Mileage (notebook photo): per-mile rate $0.70 (IRS Notice 2025-5, 2025)
mi_total, mi_larkspur, mi_cowork, mi_misc = 4860, 1200, 2232, 1150
mi_business = mi_total - mi_larkspur - mi_cowork
line9 = round(mi_business * 0.70, 2)

lines = {
    '1': line1,
    '5a': 0.00,            # 1099-K box 5a total payments card not processed through third party = $0
    '5b': 1866.68,         # 1099-K box 5b
    '9': line9,
    '10': line10,
    '15': round(hiscox, 2),
    '20b': round(cowork, 2),
    '24a': round(airfare_sfo + hotel, 2),
    '24b': round(meals_100 * 0.50, 2),
    '25': round(phone + internet, 2),
    '27a': round(figma + adobe + reg + macbook, 2),
}
net_lines = {k: (v if v != int(v) or isinstance(v, float) else v) for k, v in lines.items()}
total_exp = round(sum(lines.values()), 2)
net_profit = round(line1 - total_exp, 2)
lines['28'] = total_exp
lines['29'] = net_profit
lines['31'] = net_profit

sched_c_net = net_profit
net_earnings = round(sched_c_net * 0.9235, 2)
se_tax = round(net_earnings * 0.153, 2)
half_se = round(se_tax / 2, 2)

not_on_c = [
    {'item': 'Larkspur Design Group wages (Form W-2, box 1 $24,800)', 'schedule': 'Form 1040, line 1a', 'amount': 24800.00, 'note': 'Bank deposits $19,502.80 net of W-2 withholding (fed $2,310.00, SS $1,537.60, Medicare $359.60); reported from W-2, not Schedule C'},
    {'item': 'Health insurance - Blue Cross Blue Shield (12 x $253.34)', 'schedule': 'Schedule 1, line 17', 'amount': round(bcbs, 2), 'note': 'Library excerpt (line 15): health insurance premiums not on Schedule C line 15; reported on Schedule 1'},
    {'item': 'Deductible part of self-employment tax', 'schedule': 'Schedule 1, line 15', 'amount': half_se, 'note': 'Per Schedule SE excerpt'},
    {'item': 'Federal estimated tax payments (4 x $1,625)', 'schedule': 'Form 1040 payment credits', 'amount': round(fed_es, 2), 'note': 'Estimated income tax payments are not deductible (IRC 262 / no library authority permitting deduction); unverified in library beyond IRC 262'},
    {'item': 'Capital Factory interest income', 'schedule': 'Schedule B', 'amount': 55.93, 'note': 'Bank 12/11/2025; interest is not Schedule C receipts'},
    {'item': 'Tessaro Studio payment received 12/27/2024 ($3,000)', 'schedule': '2024 return (not 2025)', 'amount': 3000.00, 'note': 'Cash-method: 2024 income; excluded from 2025 line 1'},
    {'item': 'Personal spending (rent $19,800.00 incl. $148.50 reversals, groceries, gym, Netflix, Spotify, wedding gift, Total Affinia payment, AUS-DEN flight $389.00 pending purpose)', 'schedule': 'None - not deductible', 'amount': 0.00, 'note': 'IRC 262(a); listed in classification.csv'},
]

payload = {
    'year': 2025,
    'taxpayer': 'Dana Okafor',
    'business': 'Design studio (sole proprietor)',
    'method': 'cash',
    'lines': lines,
    'schedule_se': {
        'net_earnings': net_earnings,
        'se_tax': se_tax,
        'deductible_half': half_se,
        'wage_base_note': 'W-2 wages $24,800 + SE net earnings $35,646.52 < $176,100 base, so full 15.3% applies (excerpt)',
    },
    'not_on_schedule_c': not_on_c,
    'assumptions': [
        f'Income: 1099-K gross $41,350 (61 payment transactions, $0 card-not-processed) + $9,400 direct Tessaro ACH; 1099-NEC income from Beacon ($18,500) and Orchard ($12,200) assumed already inside PayHub gross because the same payers never deposited outside PayHub - pending Q1 confirmation',
        'Bank PAYHUB PAYOUTs total $40,150.85 = 97.1% of 1099-K gross, implying 2.9% processor fee $1,199.15 (line 10)',
        'Mileage: 4,860 total less Larkspur commuting 1,200 less coworking commuting 2,232 = 1,428 business miles x $0.70; includes 1,150 "misc client errands (see pg 2)" accepted as business pending page 2 (Q6)',
        'Phone/internet 100% business use pending substantiation (Q5)',
        'SF trip meals assumed business (Q3); Denver flight assumed personal (Q2)',
        'MacBook expensed under de minimis safe harbor; election statement to be attached; 100% business use pending (Q4)',
    ],
}
json.dump(payload, open(OUT_JSON, 'w'), indent=2)

print(f"line1={line1} exp={total_exp} net={net_profit} SE={net_earnings}/{se_tax}/{half_se}")
print(f"l10={line10} phone+net={phone+internet} cowork={cowork} figma={figma} adobe={adobe}")
print('classification counts:', {c: sum(1 for x in cls if x[0] == c) for c in set(x[0] for x in cls)})

