#!/usr/bin/env python3
"""2025 prep for Dana Okafor — current fixture (docs dated 2026-10-22).
Generates deliverable/classification.csv and deliverable/schedule_c.json
from workspace/documents/bank_checking_2024-12_to_2026-01.csv."""
import csv, json

CSV = '/work/workspace/documents/bank_checking_2024-12_to_2026-01.csv'
OUT_CSV = '/work/workspace/deliverable/classification.csv'
OUT_JSON = '/work/workspace/deliverable/schedule_c.json'

rows = list(csv.DictReader(open(CSV)))

# ---------------- classification rules ----------------
def classify(r):
    d = r['description']; amt = float(r['amount'])
    if r['date'].startswith('2024'):
        if 'TESSARO' in d:
            return ('prior_year', '', 'Payment received 12/27/2024 — 2024 income (cash method); 2025 Form 1099-NEC covers only 2025 payments')
        return ('prior_year', '', 'Dated 2024 — outside 2025 tax year (personal groceries; not on 2025 return)')
    if d.startswith('PAYHUB PAYOUT'):
        return ('business_income', '1', 'PayHub payouts = 97.1% of 1099-K gross (2.9% processor fee, line 10); gross reported on line 1; payout detail pending (Q1)')
    if 'TESSARO' in d:
        return ('business_income', '1', 'Direct ACH from Tessaro Studio; on 2025 Form 1099-NEC ($9,400: 2,400+3,100+2,150+1,750) and not in PayHub gross')
    if 'LARKSPUR' in d:
        return ('other_schedule', '', 'Wages per 2025 Form W-2 (box 1 $24,800) — Form 1040 line 1a, not Schedule C')
    if 'SOUTHWEST AIR' in d and 'AUS-SFO' in d:
        return ('business_expense', '24a', 'Airfare $412 to San Francisco client meetings Oct 5-7; substantiated by client email + hotel/meal corroboration')
    if 'SOUTHWEST AIR' in d and 'AUS-DEN' in d:
        return ('personal', '', 'AUS-DEN flight $389 Jun 13; purpose not stated in any document — treated personal pending client answer (Q2)')
    if 'HOTEL ZEPHYR' in d:
        return ('business_expense', '24a', 'Lodging $618, SF client-meeting trip Oct 5-7')
    if 'MARINA DELI' in d or 'TARTINE' in d:
        return ('business_expense', '24b', 'Meal on SF trip; 50% limitation (Pub 463): 50% x amount on line 24b; business purpose pending confirmation (Q3)')
    if 'DESIGNWEEK' in d:
        return ('business_expense', '27a', 'Professional development/conference registration $650 (excerpt: professional development on line 27a)')
    if 'MACBOOK PRO' in d:
        return ('business_expense', '27a', 'Computer $2,149 < $2,500 de minimis safe harbor (Reg. 1.263(a)-1(f), per excerpt) — expensed here; election statement required; 100% business use pending (Q4)')
    if 'CAPITAL FACTORY' in d:
        return ('business_expense', '20b', 'Coworking space rent $350 x 8 (May-Dec) = $2,800 (excerpt: rent on line 20b)')
    if d.startswith('T-MOBILE'):
        return ('business_expense', '25', 'Phone $85 x 12 = $1,020; 80% business use assumed pending substantiation (Q5); IRC 262: personal share nondeductible')
    if 'SPECTRUM INTERNET' in d:
        return ('business_expense', '25', 'Internet $70 x 12 = $840; 80% business use assumed pending substantiation (Q5)')
    if d.startswith('HISCOX'):
        return ('business_expense', '15', 'Professional liability insurance (not health) $480 — line 15')
    if 'BLUE CROSS BLUE SHIELD' in d:
        return ('other_schedule', '', 'Health insurance premiums — Schedule 1 line 17 per library excerpt (line 15 note); not on Schedule C')
    if 'IRS USATAXPYMT' in d:
        return ('tax_payment', '', 'Federal estimated tax payment — not deductible on Schedule C; credited on Form 1040')
    if d.startswith('ZELLE TO:'):
        return ('personal', '', 'Personal rent (IRC 262)')
    if 'NETFLIX' in d: return ('personal', '', 'Personal entertainment (IRC 262)')
    if 'ORANGETHEORY' in d: return ('personal', '', 'Personal gym dues (IRC 262)')
    if 'H-E-B' in d: return ('personal', '', 'Personal groceries (IRC 262)')
    if 'WEDDING GIFT' in d: return ('personal', '', 'Personal gift (IRC 262)')
    if 'FIGMA' in d: return ('business_expense', '27a', 'Software subscription $45 x 12 = $540 (excerpt: software subscriptions on line 27a)')
    if d.startswith('ADOBE'): return ('business_expense', '27a', 'Software subscription $59.99 x 12 = $719.88 (excerpt: software subscriptions on line 27a)')
    return ('other', '', 'Unclassified — review')

cls = [classify(r) for r in rows]

with open(OUT_CSV, 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['date', 'description', 'amount', 'classification', 'schedule_c_line', 'note'])
    for r, (c, ln, note) in zip(rows, cls):
        w.writerow([r['date'], r['description'], f"{float(r['amount']):.2f}", c, ln, note])

# ---------------- aggregation (expenses as positive) ----------------
def dsum(test, year='2025'):
    return sum(float(r['amount']) for r in rows if r['date'].startswith(year) and test(r['description']))

hiscox = -dsum(lambda d: d.startswith('HISCOX'))
phone = -dsum(lambda d: d.startswith('T-MOBILE'))
internet = -dsum(lambda d: 'SPECTRUM INTERNET' in d)
cowork = -dsum(lambda d: 'CAPITAL FACTORY' in d)
airfare_sfo = -dsum(lambda d: 'SOUTHWEST AIR' in d and 'AUS-SFO' in d)
hotel = -dsum(lambda d: 'HOTEL ZEPHYR' in d)
meals_100 = -dsum(lambda d: 'MARINA DELI' in d or 'TARTINE' in d)
figma = -dsum(lambda d: 'FIGMA' in d)
adobe = -dsum(lambda d: d.startswith('ADOBE'))
reg = -dsum(lambda d: 'DESIGNWEEK' in d)
macbook = -dsum(lambda d: 'MACBOOK PRO' in d)
wages_net = dsum(lambda d: 'LARKSPUR' in d)
bcbs = -dsum(lambda d: 'BLUE CROSS BLUE SHIELD' in d)
fed_es = -dsum(lambda d: 'IRS USATAXPYMT' in d)
rent = -dsum(lambda d: d.startswith('ZELLE TO:'))

# Income: 1099-K gross $41,350 (61 payment txns; box 5a $0.00, 5b $1,866.68).
# Bank PAYHUB PAYOUT sum $40,150.85 = 41,350 x 0.971 exactly -> 2.9% fee $1,199.15 (line 10).
# Beacon $18,500 + Orchard $12,200 NECs assumed inside PayHub gross (no separate deposits; client email).
gross_1099k = 41350.00
tessaro_direct = 9400.00          # 2,400 + 3,100 + 2,150 + 1,750 (2025 credits; matches 1099-NEC)
line1 = gross_1099k + tessaro_direct
line10 = round(gross_1099k * 0.029, 2)

# Mileage (notebook photo): $0.70/mi for 2025 (IRS Notice 2025-5)
mi_total, mi_larkspur, mi_cowork, mi_misc = 4860, 1200, 2232, 1150
mi_business = mi_total - mi_larkspur - mi_cowork   # 1,428
line9 = round(mi_business * 0.70, 2)

UTIL_PCT = 0.80   # ASSUMPTION pending Q5
lines = {
    '1': round(line1, 2),
    '5a': 0.00,
    '5b': 1866.68,
    '9': line9,
    '10': line10,
    '15': round(hiscox, 2),
    '20b': round(cowork, 2),
    '24a': round(airfare_sfo + hotel, 2),
    '24b': round(meals_100 * 0.50, 2),
    '25': round((phone + internet) * UTIL_PCT, 2),
    '27a': round(figma + adobe + reg + macbook, 2),
}
total_exp = round(sum(lines.values()), 2)
net_profit = round(line1 - total_exp, 2)
lines['28'] = total_exp
lines['29'] = net_profit
lines['31'] = net_profit

net_earnings = round(net_profit * 0.9235, 2)
se_tax = round(net_earnings * 0.153, 2)
half_se = round(se_tax / 2, 2)

not_on_c = [
    {'item': 'Larkspur Interactive wages (Form W-2, box 1 $24,800)', 'schedule': 'Form 1040, line 1a', 'amount': 24800.00,
     'note': 'Bank deposits total $19,502.80 net of W-2 withholding (fed $2,310.00, SS $1,537.60, Medicare $359.60); reported from W-2, not Schedule C'},
    {'item': 'Health insurance — Blue Cross Blue Shield (12 x $253.34)', 'schedule': 'Schedule 1, line 17', 'amount': round(bcbs, 2),
     'note': 'Library excerpt (line 15): health insurance premiums are not deducted on Schedule C; reported on Schedule 1'},
    {'item': 'Deductible part of self-employment tax', 'schedule': 'Schedule 1, line 15', 'amount': half_se,
     'note': 'Per Schedule SE excerpt'},
    {'item': 'Federal estimated tax payments (Q1 $1,500, Q2 $2,500, Q3 $2,500)', 'schedule': 'Form 1040 payment credits', 'amount': round(fed_es, 2),
     'note': 'Estimated federal income tax payments are not deductible; library has no authority permitting deduction (unverified beyond IRC 262)'},
    {'item': 'Tessaro Studio payment received 12/27/2024 ($3,000)', 'schedule': '2024 return (not 2025)', 'amount': 3000.00,
     'note': 'Cash method: 2024 income; excluded from 2025 line 1; the 2025 NEC ($9,400) covers only the four 2025 credits'},
    {'item': 'Personal spending: rent $19,800.00 (12 x $1,650), groceries $2,118.10 (12 x 2025 + 1 x 2024 excluded), gym $588.00, Netflix $185.88, OrangeTheory $588.00, wedding gift $200.00, AUS-DEN flight $389.00 (purpose pending Q2)', 'schedule': 'None — not deductible', 'amount': 0.00,
     'note': 'IRC 262(a); every item is itemized in classification.csv'},
]

payload = {
    'year': 2025,
    'taxpayer': 'Dana Okafor',
    'business': 'Design studio (sole proprietor, Okafordesign)',
    'method': 'cash',
    'lines': lines,
    'schedule_se': {
        'net_earnings': net_earnings,
        'se_tax': se_tax,
        'deductible_half': half_se,
        'wage_base_note': 'W-2 wages $24,800 + net earnings $35,646.52 = $60,446.52 < $176,100 wage base, so the full 15.3% rate applies (excerpt)',
    },
    'not_on_schedule_c': not_on_c,
    'assumptions': [
        'Income: 1099-K gross $41,350 (61 payment transactions; $0 card-not-processed) + $9,400 direct Tessaro ACH. Beacon ($18,500) and Orchard ($12,200) 1099-NEC income assumed already inside PayHub gross: client email says most clients pay through PayHub and the bank export shows no separate deposits from those payers; each payment counted once (excerpt, line 1). Pending Q1 confirmation',
        'Bank PAYHUB PAYOUTs total $40,150.85 = 97.1% of $41,350 exactly, implying a 2.9% processor fee of $1,199.15 kept on line 10 rather than netted against line 1 (excerpt, line 10)',
        'Mileage: notebook total 4,860 less Larkspur commuting 1,200 less Capital Factory commuting 2,232 = 1,428 business miles x $0.70 (Notice 2025-5); includes 1,150 "misc client errands (see pg 2)" accepted as business pending page 2 (Q6)',
        'Phone/internet at 80% business use is an assumption pending substantiation (Q5); IRC 262 and the excerpt (line 25: first basic home phone line nondeductible) bar the personal share',
        'SF trip meals ($64 + $126) assumed business-related, limited to 50% (Pub 463) — Q3',
        'Denver flight 6/13 assumed personal for now — Q2',
        'MacBook Pro $2,149 expensed under the de minimis safe harbor (Reg. 1.263(a)-1(f) $2,500 threshold per excerpt); election statement to be attached with the return; 100% business use pending Q4',
    ],
}
json.dump(payload, open(OUT_JSON, 'w'), indent=2)

print(f"line1={line1} exp={total_exp} net={net_profit} SE={net_earnings}/{se_tax}/{half_se}")
print(f"l9={line9} l10={line10} l25={(phone+internet)*UTIL_PCT} cowork={cowork} figma={figma} adobe={adobe} bcbs={bcbs} es={fed_es} rent={rent} wages_net={wages_net}")
print('counts:', {c: sum(1 for x in cls if x[0] == c) for c in sorted(set(x[0] for x in cls))})

